//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::repr::decimal_u64`; the
//! native twin is `benches/native/Bench/ReprDecimalU64.lean`.
//! values of 2^62 or so (lean_string_of_usize); one new string object on both sides

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::repr;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(acc, {
            let mut buf = [0u8; 20];
            make_ascii_string(repr::decimal_u64(nat_unbox(nat_box(x >> 1)), &mut buf).as_bytes())
                .byte_size()
        });
    }
    acc
}

fn main() {
    run(|| (), kernel)
}
